//! Asserts the cross-language golden dataset generated by `tests/dataset/extract_usages.py`.

// Exact float comparisons mirror the other engines' tests.
#![allow(clippy::float_cmp, clippy::type_complexity)]

mod common;

use std::path::Path;

use common::utc;
use genai_prices::{Error, ExtractRequest, PriceRequest, Usage};
use serde::Deserialize;

#[derive(Deserialize)]
struct Row {
    body: serde_json::Value,
    extracted: Vec<Extracted>,
    model: Option<String>,
}

#[derive(Deserialize)]
struct Extracted {
    extractors: Vec<Extractor>,
    usage: Usage,
}

#[derive(Deserialize)]
struct Extractor {
    api_flavor: String,
    provider_id: String,
    input_price: Option<String>,
    output_price: Option<String>,
    total_price: Option<String>,
}

#[test]
fn dataset() {
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../tests/dataset/usages.json");
    let rows: Vec<Row> = serde_json::from_slice(&std::fs::read(path).unwrap()).unwrap();
    let mut failures = Vec::new();
    for (index, row) in rows.iter().enumerate() {
        let body = serde_json::to_vec(&row.body).unwrap();
        for expected in &row.extracted {
            for extractor in &expected.extractors {
                let label = format!("row {} {}/{}", index + 1, extractor.provider_id, extractor.api_flavor);
                let request = ExtractRequest::new(body.clone())
                    .with_provider_id(&extractor.provider_id)
                    .with_api_flavor(&extractor.api_flavor);
                let actual = match genai_prices::extract_usage(&request) {
                    Ok(actual) => actual,
                    Err(error) => {
                        failures.push(format!("{label}: extract: {error}"));
                        continue;
                    }
                };
                if actual.model != row.model {
                    failures.push(format!("{label}: model {:?}, want {:?}", actual.model, row.model));
                }
                for (key, &want) in &expected.usage {
                    match actual.usage.get(key) {
                        Some(&got) if (got - want).abs() <= 1e-12 => {}
                        got => failures.push(format!("{label}: usage {key} = {got:?}, want {want}")),
                    }
                }
                let Some(model) = actual.model else { continue };
                let request = PriceRequest::new(model, actual.usage)
                    .with_provider_id(&extractor.provider_id)
                    .with_timestamp(utc(2025, 11, 6, 12, 0, 0));
                let calculation = match genai_prices::calculate(&request) {
                    Ok(calculation) => calculation,
                    Err(Error::ModelNotFound(_))
                        if extractor.input_price.is_none()
                            && extractor.output_price.is_none()
                            && extractor.total_price.is_none() =>
                    {
                        continue;
                    }
                    Err(error) => {
                        failures.push(format!("{label}: calculate: {error}"));
                        continue;
                    }
                };
                let mut check = |name: &str, actual: f64, expected: Option<&String>| match expected {
                    Some(expected) if (actual - expected.parse::<f64>().unwrap()).abs() <= 5e-9 => {}
                    expected => failures.push(format!("{label}: {name} price {actual}, want {expected:?}")),
                };
                check("input", calculation.input_price, extractor.input_price.as_ref());
                check("output", calculation.output_price, extractor.output_price.as_ref());
                if extractor.total_price.is_some() {
                    check("total", calculation.total_price, extractor.total_price.as_ref());
                }
            }
        }
    }
    assert!(failures.is_empty(), "{} dataset mismatches:\n{}", failures.len(), failures.join("\n"));
}
